-- testimonials (5)
INSERT OR IGNORE INTO testimonials (id, name, company, role, rating, text, image_media_id, sort_order) VALUES (1, 'Mehmet', 'Lada Wedding', NULL, 5, 'Bey Digital Media ile çalışmak mükemmel bir deneyimdi. E-ticaret sitemizin satışları %150 arttı. SEO ve sosyal medya stratejileri gerçekten işe yarıyor.', NULL, 1);
INSERT OR IGNORE INTO testimonials (id, name, company, role, rating, text, image_media_id, sort_order) VALUES (2, 'Erenalp Guzgun', 'Guzgun Tekstil', NULL, 5, 'Uzun zamandır sosyal medyada böyle düzenli ve yaratıcı içerikler görmemiştik. Bey Digital Media sayesinde sayfamız adeta kendini buldu diyebiliriz. Her detayı özenle takip etmeleri ve bizi biz gibi yansıtmaları işin en güzel yanı. Emeğinize sağlık!', NULL, 2);
INSERT OR IGNORE INTO testimonials (id, name, company, role, rating, text, image_media_id, sort_order) VALUES (3, 'Erkutay Torun', 'Emfa Pet', NULL, 5, 'Kurumsal web sitemizin yeniden tasarımında gösterdikleri profesyonellik takdire şayan. Modern, hızlı ve kullanıcı dostu bir site oldu.', NULL, 3);
INSERT OR IGNORE INTO testimonials (id, name, company, role, rating, text, image_media_id, sort_order) VALUES (4, 'Murat Adlığ', 'Nil Forklift', NULL, 5, 'Sosyal medya yönetimi konusunda gerçekten profesyonel bir ekip. Sayfamızın etkileşimi kısa sürede ciddi oranda arttı. Tavsiye ederim.', NULL, 4);
INSERT OR IGNORE INTO testimonials (id, name, company, role, rating, text, image_media_id, sort_order) VALUES (5, 'Ebru Özpehlivan', 'İşbir Yatak', NULL, 5, 'Logo ve kurumsal kimlik çalışmamız tam istediğimiz gibi oldu. Yiğit Bey''in renk psikolojisine hakimiyeti projemizi bir üst seviyeye taşıdı.', NULL, 5);

-- faqs (6)
INSERT OR IGNORE INTO faqs (id, question, answer, sort_order) VALUES (1, 'Sosyal medya yönetimi ve AI otomasyonu markama nasıl entegre ediliyor?', 'Geleneksel içerik üretiminin ötesine geçiyoruz. Markanızın dijital varlığını inşa ederken, hedef kitlenizle güçlü ve organik bir bağ kuracak stratejiler geliştiriyoruz. Aynı zamanda operasyonlarınızı yormayacak zeki chatbotlar ve otomasyon algoritmalarıyla etkileşimi 7/24 sürdürülebilir bir noktaya taşıyoruz.', 1);
INSERT OR IGNORE INTO faqs (id, question, answer, sort_order) VALUES (2, 'Meta Ads ve Google Ads yönetiminde nasıl bir strateji izliyorsunuz?', 'Bütçenizi rastgele yakmıyoruz. Veri bilimi ve ileri düzey hedefleme yöntemlerini kullanarak doğrudan satın alma eğilimi yüksek kitleleri tespit ediyoruz. Amacımız sadece görünürlük değil, markanızı sektör lideri konumuna taşıyacak ve maksimum ROAS''ı elde etmenizi sağlayacak kurgular oluşturmaktır.', 2);
INSERT OR IGNORE INTO faqs (id, question, answer, sort_order) VALUES (3, 'Web tasarım süreçlerinizde nelere dikkat ediyorsunuz?', 'Kullanıcıyı yoran, hantal şablonlar yerine; modern, pürüzsüz animasyonlara sahip ve kullanıcı dostu tasarımlar geliştiriyoruz. Her bir pikseli kurumsal kimliğinize uygun işliyor, ziyaretçinin sitenize girdiği an premium bir deneyim yaşamasını hedefliyoruz. Arayüzlerimiz, tamamen sizin dijital merkeziniz olarak kurgulanır.', 3);
INSERT OR IGNORE INTO faqs (id, question, answer, sort_order) VALUES (4, 'SEO (Arama Motoru Optimizasyonu) çalışmalarınız ne zaman etki eder?', 'Algoritmaları manipüle eden geçici taktiklerle değil, uzun vadeli ve sağlam bir otorite inşası ile ilerliyoruz. Arama sorgularında otoritenizi sabitlemek, sektörün rekabetine göre ortalama 1-6 ay sürer. Doğru stratejiler kurgulandığında, arama sonuçlarında sarsılmaz bir konuma ulaşırsınız.', 4);
INSERT OR IGNORE INTO faqs (id, question, answer, sort_order) VALUES (5, 'Raporlama süreci ve şeffaflık vizyonunuz nedir?', 'Sadece kalıplaşmış vaatler değil, salt veri sunuyoruz. Erişim, ROAS, dönüşüm oranları ve büyüme trendlerini size net ve şeffaf grafiklerle raporluyoruz. Neyin iyi dönüştüğünü, hangi hamlenin optimize edilmesi gerektiğini gizlilik perdesi olmadan göreceksiniz. Çünkü markanızın gelişimi, başarımızın yegane kanıtıdır.', 5);
INSERT OR IGNORE INTO faqs (id, question, answer, sort_order) VALUES (6, 'Tüm ihtiyacımı tek bir yer (Bey Digital Media) ile çözebilir miyim?', 'Kesinlikle. Logo tasarımından yapay zeka yapılarına, performans pazarlamasından kompleks web yazılımlarına kadar dijital varlığınız için gereken her şeyi tek bir yapı içinde sunuyoruz. Dağınık sistemler yerine, tüm platformların birbiriyle konuştuğu kusursuz bir ekosistem inşa ediyoruz.', 6);

