INSERT OR IGNORE INTO pages (id, slug, title, content, meta_title, meta_description) VALUES (1, 'home', 'Ana Sayfa', '[{"blockType":"hero","icerik":{"titlePrefix":"Dijital","titleSuffix":"Çözümleri","subtitle":"Türkiye''nin önde gelen dijital pazarlama ajansı olarak markanızı büyütmek için buradayız."},"cta":{"primaryCta":{"text":"Ücretsiz Teklif Al","link":"#contact"},"secondaryCta":{"text":"Hizmetlerimizi Keşfet","link":"#services"}}},{"blockType":"marquee","items":[{"text":"Sosyal Medya"},{"text":"Meta Ads"},{"text":"Google Ads"},{"text":"Web Tasarım"},{"text":"SEO"},{"text":"Logo Tasarımı"},{"text":"Kurumsal Kimlik"},{"text":"Dijital Büyüme"}]},{"blockType":"servicesGrid","sectionTitle":"Hizmetlerimiz","showAllServices":true},{"blockType":"portfolioSlider","title":"Gerçek Başarı Hikayeleri","subtitle":"Türkiye''nin önde gelen markalarıyla çalışarak dijital dünyada ölçülebilir sonuçlar elde ediyoruz.","showAllPortfolios":true},{"blockType":"testimonialsCarousel","title":"Bizim Hakkımızda Ne Dediler?","showAllTestimonials":true},{"blockType":"faqAccordion","title":"Merak Ettikleriniz","subtitle":"Dijital pazarlama ve hizmetlerimiz hakkında en çok sorulan soruların cevapları.","showAllFaqs":true},{"blockType":"about","title":"Hakkımızda","content":"Bey Digital Media olarak 8 yılı aşkın süredir markaların dijital dünyada büyümesine yardımcı oluyoruz."}]', 'Bey Digital Media | Dijital Pazarlama Ajansı', 'Dijital pazarlama ajansi. Sosyal medya yonetimi, web tasarim, SEO ve kurumsal kimlik calismalari ile markanizi buyutuyoruz.');
INSERT OR IGNORE INTO pages (id, slug, title, content, meta_title, meta_description) VALUES (2, 'about', 'Hakkımızda', '[{"blockType":"about","title":"Hakkımızda","content":"Bey Digital Media olarak 8 yılı aşkın süredir markaların dijital dünyada büyümesine yardımcı oluyoruz.","stats":[{"value":"150+","label":"Tamamlanan Proje"},{"value":"100+","label":"Memnun Müşteri"},{"value":"8+","label":"Yıllık Deneyim"},{"value":"%100","label":"Müşteri Memnuniyeti"}],"image":null}]', 'Hakkımızda | Bey Digital Media', 'Bey Digital Media, 8 yılı aşkın deneyimiyle markaların dijital dünyada büyümesine yardımcı oluyor.');

